pub fn render(cfg: &ParallelConfig) -> String {
    let mut p = match prepare(cfg) {
        Some(v) => v,
        None => return String::new(),
    };
    for ai in 0..p.n_axes {
        p.mins[ai] = 0.0;
        p.maxs[ai] = 100.0;
    }
    let n = cfg.series_values.len().min(cfg.series_names.len()).min(cfg.categories.len());
    if n == 0 {
        return String::new();
    }

    let mut cats: Vec<i32> = Vec::new();
    for si in 0..n {
        let c = cfg.categories[si];
        if c >= 0 && !cats.contains(&c) {
            cats.push(c);
        }
    }
    let mut peak_of: Vec<(i32, usize)> = Vec::with_capacity(cats.len());
    for &cat in &cats {
        let mut best_axis = 0usize;
        let mut best_spread = f64::INFINITY;
        for ai in 0..p.n_axes {
            let mut mn = f64::INFINITY;
            let mut mx = f64::NEG_INFINITY;
            let mut any = false;
            for si in 0..n {
                if cfg.categories[si] != cat || ai >= cfg.series_values[si].len() {
                    continue;
                }
                let v = cfg.series_values[si][ai];
                mn = mn.min(v);
                mx = mx.max(v);
                any = true;
            }
            if any && (mx - mn) < best_spread {
                best_spread = mx - mn;
                best_axis = ai;
            }
        }
        peak_of.push((cat, best_axis));
    }

    let mut b = open(cfg, &p);

    for si in 0..n {
        if cfg.categories[si] < 0 {
            continue;
        }
        write_curve(&mut b, &p, &cfg.series_values[si], &hex6(0xCBD5E1), 1.0, 0.22, si, "");
    }
    for si in 0..n {
        if cfg.categories[si] >= 0 {
            continue;
        }
        write_curve(&mut b, &p, &cfg.series_values[si], &hex6(0xCBD5E1), 1.0, 0.30, si, "");
    }
    const HALF_WINDOW: usize = 3;
    for si in 0..n {
        let cat = cfg.categories[si];
        if cat < 0 {
            continue;
        }
        let peak = peak_of.iter().find(|(c, _)| *c == cat).map(|(_, a)| *a).unwrap_or(0);
        let start = peak.saturating_sub(HALF_WINDOW);
        let end = (peak + HALF_WINDOW).min(p.n_axes.saturating_sub(1));
        let vals = &cfg.series_values[si];
        let window = &vals[start.min(vals.len())..(end + 1).min(vals.len())];
        let col = palette_color(cfg.palette, cat as usize);
        super::common::write_curve_from(&mut b, &p, start, window, &hex6(col), 2.0, 0.82, si, &cfg.series_names[si]);
    }

    timeline_dots(&mut b, cfg, &p, p.pad_t - 16);
    timeline_dots(&mut b, cfg, &p, p.pad_t + p.plot_h + 16);

    for &(cat, best_axis) in &peak_of {
        let name = (0..n)
            .find(|&si| cfg.categories[si] == cat && !cfg.series_names[si].is_empty())
            .map(|si| cfg.series_names[si].as_str())
            .unwrap_or("");
        let col = palette_color(cfg.palette, cat as usize);
        let x = axis_x(&p, best_axis);
        let ly = p.pad_t + p.plot_h + 20;
        push_b(&mut b, b"<circle cx=\"");
        push_f2(&mut b, x);
        push_b(&mut b, b"\" cy=\"");
        push_i(&mut b, ly);
        push_b(&mut b, b"\" r=\"3.5\" fill=\"#");
        b.extend_from_slice(&hex6(col));
        push_b(&mut b, b"\"/>");
        push_b(&mut b, b"<text x=\"");
        push_f2(&mut b, x + 6.0);
        push_b(&mut b, b"\" y=\"");
        push_i(&mut b, ly + 3);
        push_b(&mut b, b"\" transform=\"rotate(-32 ");
        push_f2(&mut b, x + 6.0);
        push_b(&mut b, b" ");
        push_i(&mut b, ly + 3);
        push_b(&mut b, b")\" text-anchor=\"start\" font-family=\"-apple-system,Arial,sans-serif\" font-size=\"9\" font-weight=\"600\" fill=\"#");
        b.extend_from_slice(&hex6(col));
        push_b(&mut b, b"\">");
        escape_xml(&mut b, name);
        push_b(&mut b, b"</text>");
    }

    finalize(b, cfg)
}

fn axis_x(p: &Prepared, ai: usize) -> f64 {
    p.pad_l as f64 + (ai as f64 / (p.n_axes - 1) as f64) * p.plot_w as f64
}

fn timeline_dots(buf: &mut Vec<u8>, cfg: &ParallelConfig, p: &Prepared, y: i32) {
    for ai in 0..p.n_axes {
        let x = axis_x(p, ai);
        push_b(buf, b"<circle cx=\"");
        push_f2(buf, x);
        push_b(buf, b"\" cy=\"");
        push_i(buf, y);
        push_b(buf, b"\" r=\"3\" fill=\"#fff\" stroke=\"#334155\" stroke-width=\"1.2\"/>");
    }
    if y < p.pad_t {
        for ai in 0..p.n_axes {
            let x = axis_x(p, ai);
            push_b(buf, b"<text x=\"");
            push_f2(buf, x);
            push_b(buf, b"\" y=\"");
            push_i(buf, y - 10);
            push_b(buf, b"\" text-anchor=\"middle\" font-family=\"-apple-system,Arial,sans-serif\" font-size=\"9\" fill=\"#64748b\">");
            escape_xml(buf, &cfg.axes[ai]);
            push_b(buf, b"</text>");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg<'a>(
        axes: &'a [String],
        names: &'a [String],
        values: &'a [Vec<f64>],
        cats: &'a [i32],
    ) -> ParallelConfig<'a> {
        ParallelConfig {
            title: "Test",
            axes,
            series_names: names,
            series_values: values,
            categories: cats,
            width: 1000,
            height: 500,
            ..ParallelConfig::default()
        }
    }

    fn synth(n_axes: usize, n_series: usize) -> (Vec<String>, Vec<String>, Vec<Vec<f64>>, Vec<i32>) {
        let axes: Vec<String> = (0..n_axes).map(|i| format!("{}", 1900 + i * 10)).collect();
        let names: Vec<String> = (0..n_series).map(|i| if i == 0 { "A".to_string() } else { String::new() }).collect();
        let values: Vec<Vec<f64>> = (0..n_series)
            .map(|si| (0..n_axes).map(|ai| 50.0 + ((si + ai) % 7) as f64).collect())
            .collect();
        let cats: Vec<i32> = (0..n_series).map(|i| if i % 3 == 0 { 0 } else { -1 }).collect();
        (axes, names, values, cats)
    }

    #[test]
    fn renders_a_pale_context_path_plus_a_colored_convergence_window_per_labeled_series_and_a_pale_one_per_background_series() {
        let (axes, names, values, cats) = synth(6, 12);
        let html = render(&cfg(&axes, &names, &values, &cats));
        assert!(!html.is_empty());
        let n_colored = cats.iter().filter(|&&c| c >= 0).count();
        let n_bg = cats.len() - n_colored;
        assert_eq!(html.matches("<path data-idx=").count(), n_colored * 2 + n_bg);
        assert!(html.contains("class=\"sp-bg\""));
        assert!(html.contains("viewBox=\"0 0 1000 500\""));
    }

    #[test]
    fn category_convergence_point_lands_on_the_axis_with_the_tightest_spread() {
        let axes: Vec<String> = vec!["a".into(), "b".into(), "c".into()];
        let names: Vec<String> = vec!["Group".into(), String::new(), String::new()];
        let values: Vec<Vec<f64>> = vec![vec![10.0, 50.0, 90.0], vec![20.0, 50.0, 10.0], vec![80.0, 50.0, 30.0]];
        let cats: Vec<i32> = vec![0, 0, 0];
        let html = render(&cfg(&axes, &names, &values, &cats));
        assert!(html.contains(">Group<"));
    }

    #[test]
    fn empty_input_returns_empty_string() {
        let axes: Vec<String> = vec![];
        let names: Vec<String> = vec![];
        let values: Vec<Vec<f64>> = vec![];
        let cats: Vec<i32> = vec![];
        assert!(render(&cfg(&axes, &names, &values, &cats)).is_empty());
    }

    #[test]
    fn perf_rendering_many_strands_stays_fast() {
        let (axes, names, values, cats) = synth(12, 400);
        let start = std::time::Instant::now();
        let html = render(&cfg(&axes, &names, &values, &cats));
        let elapsed = start.elapsed();
        assert!(elapsed.as_millis() < 200, "rendering took too long: {elapsed:?}");
        assert!(!html.is_empty());
    }
}
